def reverse(self, output):
    out_a, out_b = output.chunk(2, 1)

    if self.affine:
        log_s, t = self.net(out_a).chunk(2, 1)
        # s = torch.exp(log_s)
        s = F.sigmoid(log_s + 2)
        # in_a = (out_a - t) / s
        in_b = out_b / s - t

    else:
        net_out = self.net(out_a)
        in_b = out_b - net_out

    return torch.cat([out_a, in_b], 1)
